import { Meta, StoryObj } from "@storybook/react";
import { fn } from "storybook/test";
import GiftDeliveryMethod from "./gift-delivery-method";
import { useState } from "react";
import { Form } from "@/core/helpers";
import { FormField, useForm } from "@/core/helpers/form-builder";
import { useTranslation } from "react-i18next";
import { createContactField } from "@/core/components/primitives/phone-or-email-fields/phone-or-email-fields";

const meta = {
  title: "Primitives/Gift Delivery Method",
  component: GiftDeliveryMethod,

  argTypes: {},
  render: function StoryComponent(args) {
    const { t } = useTranslation();

    const phoneField = createContactField({
      fieldType: "phone",
      name: "phoneNumber",
      t,
    });
    const emailField = createContactField({
      fieldType: "email",
      name: "emailAddress",
      t,
    });

    const initialForm: Form = {
      fields: new Map<string, FormField>()
        .set(phoneField.name, phoneField.field)
        .set(emailField.name, emailField.field),
    };
    const [form, , handleFieldOnChange, , , ,] = useForm(initialForm, true);

    const [selectedMethod, setSelectedMethod] = useState(args.method);

    return (
      <div>
        <GiftDeliveryMethod
          {...args}
          form={form}
          method={selectedMethod}
          onMethodChange={(name, method) => setSelectedMethod(method)}
          onContactChange={(name, value) => handleFieldOnChange(name, value)}
        />
      </div>
    );
  },
  args: { onContactChange: fn() },
} satisfies Meta<typeof GiftDeliveryMethod>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    text: "",
    showCopyButton: false,
    copyPhoneLabel: "copyPhoneNumber",
    copyEmailLabel: "copyEmailAddress",
    radioGroupName: "giftDeliveryMethod",
    radioGroupLabel: "giftDeliveryMethodHeading",
    radioLabelPhone: "textMessage",
    radioLabelEmail: "email",
    method: "phone",
    form: {} as Form,
    phoneFieldName: "phoneNumber",
    emailFieldName: "emailAddress",
  },
};

export const EmailSelected: Story = {
  args: {
    ...Primary.args,
    method: "email",
  },
};

export const WithCopyButton: Story = {
  args: {
    ...Primary.args,
    showCopyButton: true,
  },
};

export const WithText: Story = {
  args: {
    ...Primary.args,
    text: "#1 Guldkortet",
  },
};
