import styles from "./gift-delivery-method.module.less";
import { useTranslation } from "react-i18next";
import { multipleClassNames } from "@/core/helpers/string-helper";
import PhoneOrEmailFields, {
  PhoneOrEmailFieldsProps,
} from "@/core/components/primitives/phone-or-email-fields/phone-or-email-fields";
import { CopyClipboardButton } from "@/core/components/primitives/copy-clipboard-button/copy-clipboard-button";
import { LabelKey } from "@/core/labels/i18n";

type GiftDeliveryMethodProps = Omit<PhoneOrEmailFieldsProps, "radioGroupLabel" | "radioLabelPhone"> & {
  /** Text above input fields, for extra info
   * Useful for example for cases with several gift delivery methods (several recipients) */
  text?: string;
  /** Show button used to copy contact information */
  showCopyButton?: boolean;
  /** Label for copy button when phone method is selected
   * @defaultValue `copyPhoneNumber`
   */
  copyPhoneLabel?: LabelKey;
  /** Label for copy button when email method is selected
   * @defaultValue `copyEmailAddress`
   */
  copyEmailLabel?: LabelKey;
  /** Label for radio group
   * @defaultValue `giftDeliveryMethodHeading`
   */
  radioGroupLabel?: LabelKey;
  /** Label for phone radio button
   * @defaultValue `textMessage`
   */
  radioLabelPhone?: LabelKey;
};

/** Component for selecting gift delivery method (phone or email) and entering contact details
 * Uses PhoneOrEmailFields component internally, and possibility to copy contact details to clipboard
 * Use "textmessage" as default for radio label for phone radio input */
const GiftDeliveryMethod = ({
  text,
  showCopyButton,
  copyPhoneLabel = "copyPhoneNumber",
  copyEmailLabel = "copyEmailAddress",
  radioGroupLabel = "giftDeliveryMethodHeading",
  radioLabelPhone = "textMessage",
  ...phoneOrEmailProps
}: GiftDeliveryMethodProps) => {
  const { t } = useTranslation();
  const phoneValue = phoneOrEmailProps.form.fields.get(phoneOrEmailProps.phoneFieldName)?.value;
  const emailValue = phoneOrEmailProps.form.fields.get(phoneOrEmailProps.emailFieldName)?.value;

  return (
    <div className={multipleClassNames(styles.wrapper)}>
      {text && <p className={styles.bundleProductName}>{text}</p>}
      <PhoneOrEmailFields {...phoneOrEmailProps} radioGroupLabel={radioGroupLabel} radioLabelPhone={radioLabelPhone} />
      {showCopyButton && (
        <CopyClipboardButton
          textToCopy={phoneOrEmailProps.method === "phone" ? phoneValue || "" : emailValue || ""}
          copyLabel={
            phoneOrEmailProps.method === "phone" ? (t(copyPhoneLabel) as string) : (t(copyEmailLabel) as string)
          }
          size="small"
          className={styles.copyButton}
        />
      )}
    </div>
  );
};

export default GiftDeliveryMethod;
